export function getMultilingualUnitAudio(languageId: string, unitId: string): AudioSource | null {
  return unitAudio[`${languageId}:${unitId}`] ?? null;
}

export function getMultilingualTextAudio(languageId: string, text: string): AudioSource | null {
  return textAudio[`${languageId}:${text.trim()}`] ?? null;
}

